import { checkResearchSignal, withinResearchLifetime } from "./lifecycle.js";
import { ResearchError } from "./contracts.js";

export const WORK_CONTRACT_VERSION = 1 as const;
export const WORK_DIMENSIONS = ["calls", "providerAttempts", "fetchedDocuments", "fetchedBytes", "scoringPairs", "scoringWindows", "scoringTokens", "elapsedMs"] as const;
export type WorkDimension = typeof WORK_DIMENSIONS[number];
export type Work = Partial<Record<WorkDimension, number>>;
export interface WorkReservation { readonly id: string; readonly maximum: Readonly<Work>; readonly usage: Readonly<Record<WorkDimension, number | null>> }
/** Implementations must atomically reserve across ALL scopes sharing a policy allowance. */
export interface WorkLedger {
  readonly durability: "volatile" | "durable";
  limit(dimension: WorkDimension): number | null;
  reserve(id: string, maximum: Readonly<Work>, signal?: AbortSignal): Promise<WorkReservation>;
  reconcile(reservation: WorkReservation, actual: Readonly<Work>, signal?: AbortSignal): Promise<void>;
  snapshot(): Readonly<Record<WorkDimension, number | null>>;
}
function valid(work: Readonly<Work>): void {
  for (const [key, value] of Object.entries(work)) {
    if (!WORK_DIMENSIONS.includes(key as WorkDimension) || !Number.isSafeInteger(value) || value! < 0) {
      throw new ResearchError("invalid_request", "work accounting is malformed");
    }
  }
}
/** Reference host ledger. No restart safety: a new instance starts a new allowance. */
export class VolatileWorkLedger implements WorkLedger {
  readonly durability = "volatile" as const;
  private readonly limits: Readonly<Work>;
  private readonly used: Work = {};
  private readonly reservations = new Map<string, { token: WorkReservation; actual?: Readonly<Work> }>();
  constructor(limits: Readonly<Work>) { valid(limits); this.limits = Object.freeze({ ...limits }); }
  async reserve(id: string, maximum: Readonly<Work>): Promise<WorkReservation> {
    valid(maximum);
    if (this.reservations.has(id)) throw new ResearchError("invalid_request", "work effect already reserved; replay through its original scope");
    for (const [key, value] of Object.entries(maximum)) {
      const dimension = key as WorkDimension;
      if (this.limits[dimension] === undefined || (this.used[dimension] ?? 0) + value > this.limits[dimension]!) {
        throw new ResearchError("budget_exhausted", "trusted work allowance is exhausted or unavailable");
      }
    }
    for (const [key, value] of Object.entries(maximum)) this.used[key as WorkDimension] = (this.used[key as WorkDimension] ?? 0) + value;
    const token = Object.freeze({ id, maximum: Object.freeze({ ...maximum }), usage: this.snapshot() });
    this.reservations.set(id, { token });
    return token;
  }
  async reconcile(token: WorkReservation, actual: Readonly<Work>): Promise<void> {
    valid(actual);
    const record = this.reservations.get(token.id);
    if (!record || record.token !== token) throw new ResearchError("invalid_request", "unknown work reservation");
    for (const [key, value] of Object.entries(actual)) {
      if (value > (token.maximum[key as WorkDimension] ?? 0)) throw new ResearchError("budget_exhausted", "observed work exceeded its reservation");
    }
    if (record.actual) {
      if (JSON.stringify(record.actual) !== JSON.stringify(actual)) throw new ResearchError("invalid_request", "work reconciliation changed on replay");
      return;
    }
    for (const [key, value] of Object.entries(token.maximum)) this.used[key as WorkDimension]! -= value - (actual[key as WorkDimension] ?? 0);
    record.actual = Object.freeze({ ...actual });
  }
  limit(dimension: WorkDimension): number | null { return this.limits[dimension] ?? null; }
  snapshot(): Readonly<Record<WorkDimension, number | null>> {
    return Object.freeze(Object.fromEntries(WORK_DIMENSIONS.map(key => [key, this.limits[key] === undefined ? null : this.used[key] ?? 0])) as Record<WorkDimension, number | null>);
  }
}

/** One trusted call's effect identities. Failed/uncertain effects retain the full reserved charge. */
export class WorkScope {
  private readonly effects = new Map<string, { maximum: string; promise: Promise<unknown> }>();
  constructor(private readonly ledger: WorkLedger, private readonly id: string, readonly signal: AbortSignal) {}
  run<T>(effectId: string, maximum: Readonly<Work>, effect: (reservation: WorkReservation) => Promise<T>, actual: (value: T) => Readonly<Work> = () => maximum, signal: AbortSignal = this.signal): Promise<T> {
    valid(maximum);
    maximum = Object.freeze({ ...maximum });
    const serialized = JSON.stringify(maximum);
    if (signal.aborted) return Promise.reject(new ResearchError("timeout", "work was cancelled"));
    const previous = this.effects.get(effectId);
    if (previous) {
      if (previous.maximum !== serialized) return Promise.reject(new ResearchError("invalid_request", "replayed effect changed its work reservation"));
      return previous.promise as Promise<T>;
    }
    const promise = (async () => {
      const reservation = await withinResearchLifetime(
        () => this.ledger.reserve(JSON.stringify([this.id, effectId]), maximum, signal), signal);
      // A cancelled/uncertain reservation remains charged; never start its effect late.
      checkResearchSignal(signal);
      const value = await withinResearchLifetime(() => effect(reservation), signal);
      checkResearchSignal(signal);
      await withinResearchLifetime(() => this.ledger.reconcile(reservation, actual(value), signal), signal);
      checkResearchSignal(signal);
      return value;
    })();
    this.effects.set(effectId, { maximum: serialized, promise });
    return promise;
  }
}

import { checkResearchSignal, withinResearchLifetime } from "./lifecycle.js";
import { createHash } from "node:crypto";
import { ResearchEngine } from "./engine.js";
import { lexicalRanker } from "./ranker.js";
import { WorkScope, type WorkLedger } from "./work.js";
import { normalizeFocusTerms, MAXIMUM_CONTINUATION_CHUNKS } from "./documentChunks.js";
import { validateQuery, validateMaxResults, normalizePreferredDomains, PUBLIC_WEB_SOURCE_POLICY, resolveSourcePolicy, SOURCE_POLICY_RELEASE } from "./policy.js";
import { RESEARCH_LIMITS, ResearchError, researchOperationName, type CoreEvidence, type CorePolicy, type FetchInput, type TranscriptInput, type ResearchBudgetTelemetry, type ResearchResult } from "./contracts.js";
import { normalizeYoutubeLanguageTag } from "./youtubeTranscript.js";

export const CORE_RELEASE = Object.freeze({ contractVersion: 1, packageVersion: "1.3.0", selection: lexicalRanker.identity.version,
  sourcePolicy: SOURCE_POLICY_RELEASE });
export type ResearchRequest =
  | { operation: "search"; input: { query: string; maxResults?: number; preferredDomains?: readonly string[] } }
  | { operation: "fetch"; input: FetchInput }
  | { operation: "transcript"; input: TranscriptInput };
export interface TrustedResearchHost {
  readonly sessionId: string;
  readonly capabilityIdentity: string;
  readonly cacheNamespace: string;
  readonly policy: CorePolicy;
  readonly callLimit: number;
  readonly ledger: WorkLedger;
  readonly signal: AbortSignal;
  now(): Date;
  authorize(operation: ResearchRequest["operation"], signal: AbortSignal): Promise<boolean>;
  /** Idempotent evidence sink. Never receives queries, bodies, handles or credentials. */
  record(callId: string, evidence: CoreEvidence & { requestDigest: string; release: typeof CORE_RELEASE }, signal: AbortSignal): Promise<void>;
}

/** Bind once over a PRIVATE trusted setup channel. execute() accepts only research data. */
export class ResearchService {
  private readonly host: TrustedResearchHost;
  private readonly policy: CorePolicy;
  private readonly calls = new Map<string, { digest: string; result: Promise<ResearchResult<unknown>> }>();
  private readonly shutdown = new AbortController();
  constructor(private readonly engine: ResearchEngine, host: TrustedResearchHost) {
    for (const value of [host.sessionId, host.capabilityIdentity, host.cacheNamespace]) {
      if (typeof value !== "string" || !value.length || value.length > 256) throw new ResearchError("invalid_request", "trusted identity is malformed");
    }
    if (!Number.isSafeInteger(host.callLimit) || host.callLimit < 0 || host.callLimit > 4096) throw new ResearchError("invalid_request", "trusted call limit is malformed");
    if (host.ledger.limit("calls") !== host.callLimit) throw new ResearchError("invalid_request", "call limit must match the atomic host ledger");
    this.policy = freezePolicy(host.policy);
    // Snapshot identities; keep only explicitly bound host callbacks and trusted resources.
    this.host = Object.freeze({ sessionId: host.sessionId, capabilityIdentity: host.capabilityIdentity, cacheNamespace: host.cacheNamespace,
      policy: this.policy, callLimit: host.callLimit, ledger: host.ledger, signal: host.signal,
      now: host.now.bind(host), authorize: host.authorize.bind(host), record: host.record.bind(host) });
  }
  close(): void { this.shutdown.abort(); this.calls.clear(); }
  execute(callId: string, input: unknown, signal: AbortSignal = new AbortController().signal): Promise<ResearchResult<unknown>> {
    if (!/^[A-Za-z0-9._:-]{1,128}$/u.test(callId)) return Promise.reject(new ResearchError("invalid_request", "call identity is malformed"));
    let serialized: string;
    try {
      serialized = JSON.stringify(input);
      if (!serialized || Buffer.byteLength(serialized) > 16 * 1024) throw new Error();
      input = JSON.parse(serialized);
    } catch { return Promise.resolve(this.failure("invalid_request", "research request is malformed or oversized", "search")); }
    const rawOperation = input && typeof input === "object" ? (input as { operation?: unknown }).operation : undefined;
    const operation: ResearchRequest["operation"] = rawOperation === "fetch" || rawOperation === "transcript" ? rawOperation : "search";
    const digest = createHash("sha256").update(serialized).digest("hex");
    if (this.shutdown.signal.aborted || this.host.signal.aborted || signal.aborted) return Promise.resolve(this.failure("timeout", "research was cancelled", operation));
    const prior = this.calls.get(callId);
    if (prior) {
      if (prior.digest !== digest) return Promise.resolve(this.failure("invalid_request", "replayed call changed its request", operation));
      const replaySignal = AbortSignal.any([signal, this.host.signal, this.shutdown.signal]);
      // Cancel only this wait; the original execution owns its effects and result.
      return withinResearchLifetime(() => prior.result, replaySignal).catch(error => this.failure(
        replaySignal.aborted ? "timeout" : error instanceof ResearchError ? error.code : "unavailable",
        "research replay did not complete", operation));
    }
    // Bound replay state even if an untrusted client floods denied calls.
    if (this.calls.size >= 4096) return Promise.resolve(this.failure("budget_exhausted", "call replay capacity exhausted", operation));
    const result = this.perform(callId, input, operation, digest, signal);
    this.calls.set(callId, { digest, result });
    return result;
  }
  private async perform(callId: string, input: unknown, operation: ResearchRequest["operation"], digest: string, caller: AbortSignal): Promise<ResearchResult<unknown>> {
    const deadline = operation === "search" ? this.policy.values.searchDeadlineMs : this.policy.values.fetchDeadlineMs;
    const signal = AbortSignal.any([caller, this.host.signal, this.shutdown.signal, AbortSignal.timeout(deadline)]);
