    for (const [key, value] of Object.entries(actual)) {
      if (value > (token.maximum[key as WorkDimension] ?? 0)) throw new ResearchError("budget_exhausted", "observed work exceeded its reservation");
    }
    if (record.actual) {
      if (JSON.stringify(record.actual) !== JSON.stringify(actual)) throw new ResearchError("invalid_request", "work reconciliation changed on replay");
      return;
    }
